// Standalone paired experiment. The production encoder and decoder are unchanged.
#include "LocalNoise.h"
#include "LpxAccuracy.h"
#include "LpxEncoder.h"
#include "LpxFullBand.h"
#include "LpxPitchGuard.h"
#include "Lpx4HybridCore.h"
#include <fstream>
#include <iterator>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <chrono>
#include <ctime>
