namespace {
using namespace lpx;
std::vector<uint8_t> read(const std::string& path){std::ifstream f(path,std::ios::binary);if(!f)throw std::runtime_error("Cannot read PCM");return {std::istreambuf_iterator<char>(f),{}};}
Pcm loadPcm(const std::string& path){const auto b=read(path);if(b.empty()||b.size()%2)throw std::runtime_error("Empty or odd PCM length");Pcm p;for(size_t i=0;i<b.size();i+=2)p.push_back(int16_t(b[i]|uint16_t(b[i+1])<<8));return p;}
void save(const std::string& path,const std::vector<uint8_t>& bytes){std::ifstream old(path,std::ios::binary);if(old){std::vector<uint8_t> previous{std::istreambuf_iterator<char>(old),{}};if(previous==bytes)return;throw std::runtime_error("Refusing to replace a frozen artifact; select a new run name");}std::ofstream f(path,std::ios::binary);f.write(reinterpret_cast<const char*>(bytes.data()),bytes.size());if(!f)throw std::runtime_error("Cannot save artifact");}
void savePcm(const std::string& path,const Pcm& p){std::vector<uint8_t> b;for(int16_t x:p){b.push_back(x&255);b.push_back(uint16_t(x)>>8);}save(path,b);}
Pcm decode(const std::vector<uint8_t>& b){Lpx4HybridCore decoder;if(!decoder.begin(b.data(),b.size()))throw std::runtime_error("Native decoder begin failed");Pcm p;int16_t x;while(decoder.nextS16(x))p.push_back(x);if(decoder.error())throw std::runtime_error("Native decoder failed");return p;}
void saveModel(const std::string& path,const Stream& s){std::ostringstream f;f<<s.samples<<' '<<s.profile<<' '<<s.rate<<' '<<s.pre<<' '<<s.bright<<' '<<s.accuracy<<' '<<int(s.qualityTarget)<<'\n';for(const auto& v:s.spectra){for(int x:v)f<<x<<' ';f<<'\n';}for(const auto& v:s.parameters){for(int x:v)f<<x<<' ';f<<'\n';}for(const auto& v:s.pulses)f<<v[0]<<' '<<v[1]<<'\n';for(const auto& v:s.extras)f<<v[0]<<' '<<v[1]<<'\n';const auto text=f.str();save(path,std::vector<uint8_t>(text.begin(),text.end()));}
void number(double x){if(std::isfinite(x))std::cout<<x;else std::cout<<"null";}
void pair(const double* x){std::cout<<'[';number(x[0]);std::cout<<',';number(x[1]);std::cout<<']';}
void local(const LocalNoiseMeasurement& m){std::cout<<"{\"valid\":"<<(m.valid?"true":"false")<<",\"windows\":"<<m.windows<<",\"voiced_windows\":"<<m.voicedWindows<<",\"quiet_windows\":"<<m.quietWindows<<",\"transient_windows\":"<<m.transientWindows<<",\"unsupported_windows\":"<<m.unsupportedWindows<<",\"magnitude\":";pair(m.magnitude);std::cout<<",\"interharmonic\":";pair(m.interharmonic);std::cout<<",\"score\":";number(m.score);std::cout<<'}';}
struct Difference {int spectra=0,parameters=0,positions=0,amplitudes=0,extras=0;};
Difference differences(const Stream& a,const Stream& b){if(a.samples!=b.samples||a.rate!=b.rate||a.profile!=b.profile||a.pre!=b.pre||a.bright!=b.bright||a.accuracy!=b.accuracy||a.qualityTarget!=b.qualityTarget||a.continuation||b.continuation||a.allowExtras!=b.allowExtras||a.spectra.size()!=b.spectra.size()||a.parameters.size()!=b.parameters.size()||a.pulses.size()!=b.pulses.size()||a.extras.size()!=b.extras.size())throw std::runtime_error("Non-pulse model metadata changed");if(a.previousSpectrum!=b.previousSpectrum||a.previousInput!=b.previousInput||a.previousCoefficients!=b.previousCoefficients||a.lookahead!=b.lookahead||a.initial.dd!=b.initial.dd||a.initial.cc!=b.initial.cc)throw std::runtime_error("Continuation or filter state changed");for(int i=0;i<10;++i)if(a.initial.h[i]!=b.initial.h[i])throw std::runtime_error("LPC state changed");for(int i=0;i<256;++i)if(a.initial.ring[i]!=b.initial.ring[i])throw std::runtime_error("Excitation state changed");Difference d;for(size_t i=0;i<a.spectra.size();++i)for(int k=0;k<10;++k)d.spectra+=a.spectra[i][k]!=b.spectra[i][k];for(size_t i=0;i<a.parameters.size();++i)for(int k=0;k<3;++k)d.parameters+=a.parameters[i][k]!=b.parameters[i][k];for(size_t i=0;i<a.pulses.size();++i){d.positions+=a.pulses[i][0]!=b.pulses[i][0];d.amplitudes+=a.pulses[i][1]!=b.pulses[i][1];}for(size_t i=0;i<a.extras.size();++i)for(int k=0;k<2;++k)d.extras+=a.extras[i][k]!=b.extras[i][k];if(d.spectra||d.parameters||d.extras)throw std::runtime_error("Experiment changed a frozen coefficient, pitch, scale or extra pulse");return d;}
struct Observed {Stream stream;std::vector<uint8_t> bytes;Pcm pcm;Measurement quality;FullBandMeasurement full;LocalNoiseMeasurement noise,activeNoise;Difference changed;bool stable,level,spectrum,admitted,fullAccepted,activeFullAccepted,pitchAccepted,qualityFloor,voiceFloor,oldNoiseFloor;};
}
int main(int argc,char** argv){try{
 if(argc!=7)throw std::runtime_error("Usage: benchmark SOURCE_PCM OUTPUT_PREFIX LEVEL RATE pcm|pwm CALLS");
 const auto reference=loadPcm(argv[1]);const std::string prefix=argv[2],mode=argv[5];const int level=std::stoi(argv[3]),rate=std::stoi(argv[4]),calls=std::stoi(argv[6]);
 if((level!=4&&level!=6)||(rate!=8000&&rate!=12000&&rate!=16000)||(mode!="pcm"&&mode!="pwm")||calls!=4||reference.size()>64000)throw std::runtime_error("Invalid bounded experiment case");
 const QualityTarget target=mode=="pcm"?QualityTarget::Pcm:QualityTarget::Pwm;
 if(!enc_reserve(reference.size()))throw std::runtime_error("Seed reserve failed");
 const auto start=std::chrono::steady_clock::now();const auto cpuStart=std::clock();AdaptiveReport baselineReport;
 const auto baseline=encodeAccuracy(reference,level,rate,baselineReport,calls,nullptr,target);
 const auto baselineEnd=std::chrono::steady_clock::now();const auto baselineCpu=std::clock();
 if(baselineReport.error||baseline.samples!=int(reference.size())||baseline.qualityTarget!=target)throw std::runtime_error("Fresh target-specific baseline failed");
 LocalNoiseReport report;Stream raw,sseRaw,sseControl;const auto final=refineLocalNoise(baseline,reference,report,&raw,&sseRaw,&sseControl);
 const auto refineEnd=std::chrono::steady_clock::now();const auto refineCpu=std::clock();
 if(report.error)throw std::runtime_error("Local-noise refinement failed");
 if(!raw.samples)raw=baseline;if(!sseRaw.samples)sseRaw=baseline;if(!sseControl.samples)sseControl=baseline;
 // Always report both observed output paths, even when only PCM governs selection.
 QualityContext quality(reference,true,rate,QualityTarget::Pwm);FullBandContext full(reference,rate,QualityTarget::Pwm);LocalNoiseContext diagnostic(reference,rate,QualityTarget::Pwm),activeDiagnostic(reference,rate,target);
 FullBandContext policyFull(reference,rate,target);QualityContext policyQuality(reference,true,rate,target);
 const auto baselinePcm=render(baseline);const auto baselineFull=full.measure(baselinePcm),baselinePolicyFull=policyFull.measure(baselinePcm);
 const auto baselinePolicyQuality=policyQuality.measure(baselinePcm);PitchGuardContext pitch(reference,baselinePcm,rate,target);
 Observed observed[5];const Stream* streams[5]={&baseline,&raw,&sseRaw,&final,&sseControl};const char* names[5]={"baseline","raw-noise","raw-sse","final-noise","final-sse"};
 for(int i=0;i<5;++i){auto& o=observed[i];o.stream=*streams[i];o.changed=differences(baseline,o.stream);o.bytes=packV9(o.stream);o.pcm=render(o.stream);if(decode(o.bytes)!=o.pcm||o.pcm.size()!=reference.size())throw std::runtime_error("Independent model/native decode mismatch");if(i&&o.bytes.size()!=observed[0].bytes.size())throw std::runtime_error("Pulse-only proposal changed complete file size");o.quality=quality.measure(o.pcm);o.full=full.measure(o.pcm);o.noise=diagnostic.measure(o.pcm);o.activeNoise=activeDiagnostic.measure(o.pcm);o.stable=stableLpcStream(o.stream);o.level=safeSynthesisLevel(o.stream,reference,o.pcm);o.spectrum=safeSynthesisSpectrum(reference,o.pcm);o.admitted=profileQualityAdmission(reference,baselinePcm,o.pcm,rate,true,false,target);o.fullAccepted=full.accepts(o.full,baselineFull);o.activeFullAccepted=policyFull.accepts(policyFull.measure(o.pcm),baselinePolicyFull);o.pitchAccepted=pitch.accepts(o.pcm);const auto pm=policyQuality.measure(o.pcm);o.qualityFloor=noRegression(pm.quality,baselinePolicyQuality.quality);o.voiceFloor=voiceGate(pm,baselinePolicyQuality);o.oldNoiseFloor=true;for(int p=0;p<qualityPathCount(target);++p)o.oldNoiseFloor=o.oldNoiseFloor&&std::isfinite(pm.noise[p])&&pm.noise[p]<=baselinePolicyQuality.noise[p]+1e-12;}
 for(int i=3;i<5;++i)if(observed[i].bytes!=observed[0].bytes&&(!observed[i].admitted||!observed[i].stable||!observed[i].level||!observed[i].spectrum||!observed[i].qualityFloor||!observed[i].activeFullAccepted||!observed[i].pitchAccepted||!observed[i].oldNoiseFloor))throw std::runtime_error("Accepted final violates independent whole-output guards");
 for(int i=0;i<5;++i){const auto path=prefix+"."+names[i];save(path+".lpx",observed[i].bytes);savePcm(path+".pcm",observed[i].pcm);saveModel(path+".model",observed[i].stream);}
 std::cout.precision(14);std::cout<<"{\"experiment_version\":\""<<localnoise::Version<<"\",\"metric_paths\":[\"pcm\",\"pwm\"],\"samples\":"<<reference.size()<<",\"sample_rate\":"<<rate<<",\"accuracy_level\":"<<level<<",\"quality_target\":\""<<mode<<"\",\"calls\":"<<calls<<",\"native_model_exact\":true,\"pulse_only_same_complete_bytes\":true,\"baseline_seconds\":"<<std::chrono::duration<double>(baselineEnd-start).count()<<",\"refinement_seconds\":"<<std::chrono::duration<double>(refineEnd-baselineEnd).count()<<",\"baseline_cpu_seconds\":"<<double(baselineCpu-cpuStart)/CLOCKS_PER_SEC<<",\"refinement_cpu_seconds\":"<<double(refineCpu-baselineCpu)/CLOCKS_PER_SEC;
 std::cout<<",\"baseline_search\":{\"candidates\":"<<baselineReport.candidates<<",\"stages\":"<<baselineReport.stages<<",\"selected\":"<<baselineReport.selected<<",\"seed_status\":"<<int(baselineReport.originalSeedStatus)<<",\"quality_local_evaluations\":"<<baselineReport.qualitySearch.localEvaluations<<",\"quality_full_evaluations\":"<<baselineReport.qualitySearch.fullEvaluations<<",\"joint_header_full_evaluations\":"<<baselineReport.jointQuality.headerFullEvaluations<<",\"joint_lpc_proposals\":"<<baselineReport.jointQuality.lpcProposals<<'}';
 std::cout<<",\"constants\":{\"fft_samples\":"<<localnoise::FftSamples<<",\"hop_samples\":"<<localnoise::HopSamples<<",\"score_windows\":"<<localnoise::ScoreWindows<<",\"max_regions\":"<<localnoise::MaxRegions<<",\"pairs_per_region\":"<<localnoise::PairsPerRegion<<",\"sse_shortlist\":"<<localnoise::SseShortlist<<",\"max_first_choices\":"<<localnoise::MaxFirstChoices<<",\"max_horizon\":"<<localnoise::MaxHorizon<<",\"quiet_rms\":"<<localnoise::QuietRms<<",\"min_periodicity\":"<<localnoise::MinPeriodicity<<",\"max_slice_energy_ratio\":"<<localnoise::MaxSliceEnergyRatio<<",\"min_harmonic_fraction\":"<<localnoise::MinHarmonicFraction<<",\"noise_weight\":"<<localnoise::NoiseWeight<<'}';
 std::cout<<",\"search\":{\"error\":"<<report.error<<",\"regions\":"<<report.regions<<",\"pairs\":"<<report.pairs<<",\"local_evaluations\":"<<report.localEvaluations<<",\"noise_evaluations\":"<<report.noiseEvaluations<<",\"synthesized_samples\":"<<report.synthesizedSamples<<",\"proposals\":"<<report.proposals<<",\"full_evaluations\":"<<report.fullEvaluations<<",\"admitted_proposals\":"<<(report.admittedNoiseProposals+report.admittedSseProposals)<<",\"accepted\":"<<report.accepted<<",\"noise_patches\":"<<report.noisePatches<<",\"sse_patches\":"<<report.ssePatches<<",\"noise_proposals\":"<<report.noiseProposals<<",\"sse_proposals\":"<<report.sseProposals<<",\"admitted_noise_proposals\":"<<report.admittedNoiseProposals<<",\"admitted_sse_proposals\":"<<report.admittedSseProposals<<",\"selected_noise\":"<<report.selectedNoise<<",\"selected_sse\":"<<report.selectedSse<<",\"pcm_sse_evaluations\":"<<report.pcmSseEvaluations<<",\"pwm_sse_evaluations\":"<<report.pwmSseEvaluations<<",\"active_sse_evaluations\":"<<report.activeSseEvaluations<<",\"initial_objective\":";number(report.noiseSelection.initialObjective);std::cout<<",\"final_objective\":";number(report.noiseSelection.finalObjective);std::cout<<",\"sse_initial_objective\":";number(report.sseSelection.initialObjective);std::cout<<",\"sse_final_objective\":";number(report.sseSelection.finalObjective);std::cout<<",\"rejections\":{\"size\":"<<report.rejectedSize<<",\"native\":"<<report.rejectedNative<<",\"stability\":"<<report.rejectedStability<<",\"level\":"<<report.rejectedLevel<<",\"spectrum\":"<<report.rejectedSpectrum<<",\"quality\":"<<report.rejectedQuality<<",\"fullband\":"<<report.rejectedFullBand<<",\"old_noise\":"<<report.rejectedOldNoise<<",\"complete\":"<<report.rejectedComplete<<"}}";
 std::cout<<",\"source_windows\":[";
 const auto& windows=diagnostic.analysis();for(size_t i=0;i<windows.size();++i){const auto& w=windows[i];std::cout<<(i?",":"")<<"{\"start\":"<<w.start<<",\"supported\":"<<(w.supported?"true":"false")<<",\"voiced\":"<<(w.voiced?"true":"false")<<",\"quiet\":"<<(w.quiet?"true":"false")<<",\"transient\":"<<(w.transient?"true":"false")<<",\"period\":";number(w.period);std::cout<<",\"periodicity\":";number(w.periodicity);std::cout<<",\"harmonic_fraction\":";number(w.harmonicFraction);std::cout<<",\"normalization\":";number(w.normalization);std::cout<<",\"interharmonic_mask\":\"";for(auto x:w.interharmonic)std::cout<<int(x);std::cout<<"\"}";}std::cout<<']';
 std::cout<<",\"outputs\":{";
 for(int i=0;i<5;++i){const auto& o=observed[i];std::cout<<(i?",":"")<<'\"'<<names[i]<<"\":{\"bytes\":"<<o.bytes.size()<<",\"changed_positions\":"<<o.changed.positions<<",\"changed_amplitudes\":"<<o.changed.amplitudes<<",\"changed_spectral_indices\":"<<o.changed.spectra<<",\"changed_parameters\":"<<o.changed.parameters<<",\"changed_extras\":"<<o.changed.extras<<",\"stable\":"<<(o.stable?"true":"false")<<",\"level_safe\":"<<(o.level?"true":"false")<<",\"spectrum_safe\":"<<(o.spectrum?"true":"false")<<",\"quality_admission_selected_target\":"<<(o.admitted?"true":"false")<<",\"fullband_acceptance_both_paths\":"<<(o.fullAccepted?"true":"false")<<",\"fullband_acceptance_selected_target\":"<<(o.activeFullAccepted?"true":"false")<<",\"pitch_guard_selected_target\":"<<(o.pitchAccepted?"true":"false")<<",\"sse_stoi_floor_selected_target\":"<<(o.qualityFloor?"true":"false")<<",\"old_noise_floor_selected_target\":"<<(o.oldNoiseFloor?"true":"false")<<",\"voice_floor_selected_target\":"<<(o.voiceFloor?"true":"false")<<",\"pcm_sse\":"<<o.quality.quality.error[0]<<",\"pwm_sse\":"<<o.quality.quality.error[1]<<",\"stoi\":";pair(o.quality.quality.stoi);std::cout<<",\"voice\":";pair(o.quality.voice);std::cout<<",\"noise\":";pair(o.quality.noise);std::cout<<",\"clipped\":"<<o.quality.clipped<<",\"fullband_error\":";pair(o.full.balancedError);std::cout<<",\"fullband_temporal_error\":";pair(o.full.balancedTemporalError);std::cout<<",\"local_noise_diagnostic\":";local(o.noise);std::cout<<",\"local_noise_selected_target\":";local(o.activeNoise);std::cout<<'}';}
 std::cout<<"}}\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
